questionvariables.text:
/* Design backwards via the factor parametrisation
       AP = p*r,  PB = q*s,  CP = p*s,  PD = q*r,
   which makes  AP*PB = CP*PD = p*q*r*s  hold automatically for ANY p,q,r,s.
   Build the set of admissible (p,q,r,s) on the fly from the constraints, then pick
   one at random. Constraints: p#q and r#s (so each given length and the answer are
   distinct, and the additive distractor differs from the answer); AP#PB (the two
   mispairing distractors stay distinct); CP#PD (answer not equal to CP); all four
   parts in [2,12]; chord totals <= 15. Over this whole space the answer and the
   three distractors are pairwise distinct, so marking is deterministic. */
params : sublist(
  create_list([p,q,r,s], p,1,4, q,1,4, r,2,5, s,2,5),
  lambda([z], is(
        z[1]#z[2] and z[3]#z[4]
    and z[1]*z[3]#z[2]*z[4] and z[1]*z[4]#z[2]*z[3]
    and z[1]*z[3]>=2 and z[1]*z[3]<=12 and z[2]*z[4]>=2 and z[2]*z[4]<=12
    and z[1]*z[4]>=2 and z[1]*z[4]<=12 and z[2]*z[3]>=2 and z[2]*z[3]<=12
    and z[1]*z[3]+z[2]*z[4]<=15 and z[1]*z[4]+z[2]*z[3]<=15 )));
sel : rand(params);
AP : sel[1]*sel[3];
PB : sel[2]*sel[4];
CP : sel[1]*sel[4];
PD : sel[2]*sel[3];
ta1 : PD;
wrong_add : AP + PB - CP;    /* additive slip: AP + PB = CP + PD */
wrong_cross : CP*PB/AP;      /* mispairing: AP*PD = CP*PB  (paired AP with PD) */
wrong_pair : AP*CP/PB;       /* mispairing: AP*CP = PD*PB  (paired AP with CP) */
